function icon(k,cls=''){return '<svg class="i '+cls+'" viewBox="0 0 24 24" aria-hidden="true">'+(ICONS[k]||ICONS.spark)+'</svg>'}
function h(t){return String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

function ipaView(w,mini=false){
 const note=w.ipaSource==='词典重点校订'?'已针对易误读术语参考词典修订。':'英式发音由英语语音规则生成，美式按词典音素拼合；尚非逐条真人校音。';
 return `<div class="ipa-panel ${mini?'mini':''}" aria-label="英式美式音标" title="${h(note)}">
  ${[['UK','英',w.ipaUK],['US','美',w.ipaUS]].map(([accent,title,ipa])=>`<div class="ipa-row"><span class="accent-label">${title}</span><span class="ipa-text">${ipa?'/'+h(ipa)+'/':'待核验'}</span><button class="ipa-sound" data-play-accent="${accent}" data-word-id="${h(w.id)}" aria-label="播放${title}式发音">${icon('sound','sm')}</button></div>`).join('')}
 <span class="ipa-footnote">${h(w.ipaSource)} · 音频使用本机英／美语音包；复杂术语建议听音核对</span>
 </div>`;
}
function phraseView(w){return `<div class="phrase-translation"><span class="phrase-kicker">常用短语 · 中英对照</span><b>${h(w.collocation||w.term)}</b><small>中文：${h(w.collocationZh||w.zh)}</small>${w.collocationReview==='语义匹配'?'<em class="phrase-note">语义匹配译法，建议结合公司用语核对</em>':''}</div>`}
function speakAccent(id,accent){let w=byId(id);if(!w)return;speechStop();tts(w.speakTerm||w.term,accent==='UK'?'en-GB':'en-US')}

function hashText(str){let hash=2166136261;for(const ch of String(str)){hash=Math.imul(hash^ch.charCodeAt(0),16777619)}return hash>>>0}
function byId(id){return DB.words.find(x=>x.id===id)};
function modById(id){return DB.modules.find(m=>m.id===id)};
const KEY=({'/hr-fluent/':'hr-fluent-v5','/hr-fluent-staging/':'hr-fluent-v5:staging','/hr-fluent-dev/':'hr-fluent-v5:dev18'})[new URL('./',location.href).pathname] || 'hr-fluent-v5:isolated:'+new URL('./',location.href).pathname;
const STORAGE_READY=(()=>{try{let k='hrf-storage-probe';localStorage.setItem(k,'1');let ok=localStorage.getItem(k)==='1';localStorage.removeItem(k);return ok}catch(e){return false}})();
function load(){try{let s=JSON.parse(localStorage.getItem(KEY)||'{}');return {words:{},days:{},xp:0,dark:false,goal:8,rate:1,...s}}catch(e){return{words:{},days:{},xp:0,dark:false,goal:8,rate:1}}}
let STORE=load();
// V15 one-time migration: the previous app default was 0.9x. Keep all progress,
// and let learners set 0.9x again explicitly after upgrading if preferred.
if(STORE.v15SpeedMigration!==true){
 if(Number(STORE.rate)===0.9) STORE.rate=1;
 STORE.v15SpeedMigration=true;
 try{localStorage.setItem(KEY,JSON.stringify(STORE))}catch(e){}
}
STORE.quizSource=STORE.quizSource==='learned'?'learned':'all';
let state={quizSource:STORE.quizSource,tab:'home',module:'all',query:'',filter:'all',visible:24,deck:[],deckIndex:0,flipped:false,detailId:null,detailTab:'meaning',detailChoice:null,syncOpen:false,bookmarkOpen:false,sceneId:null,roleplay:false,sceneReveal:1,roleplayRole:null,roleplayStep:0,roleInput:'',roleFeedback:null,roleReference:false,roleListening:false,roleplayAnswers:{},sceneZh:true,quiz:null,quizReturn:null,toast:null};
let saveFailure=false;
function saveSnapshot(){try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch(e){return null}}
function save(){const previous=STORE.savedAt;STORE.savedAt=new Date().toISOString();try{const value=JSON.stringify(STORE);localStorage.setItem(KEY,value);if(localStorage.getItem(KEY)!==value)throw Error('写入后校验失败');saveFailure=false;refreshSavePanel();return true}catch(e){STORE.savedAt=previous;saveFailure=true;refreshSavePanel();toast('本地保存失败。请通过“我的 → 导出备份”保留进度。');return false}}
function savePanelContent(){const snap=saveSnapshot(), words=Object.values(snap?.words||{}), rows=[['已学习词汇',DB.words.filter(w=>snap?.words?.[w.id]?.seen||Number(snap?.words?.[w.id]?.level)>0).length,'个'],['收藏词汇',words.filter(w=>w.favorite).length,'个'],['短语本',(snap?.phrases||[]).length,'条'],['句子本',(snap?.sentences||[]).length,'条'],['错题记录',Object.values(snap?.wrong||{}).filter(n=>Number(n)>0).length,'个'],['练习记录',(snap?.quizHistory||[]).length,'次'],['学习足迹',Object.values(snap?.days||{}).filter(n=>Number(n)>0).length,'天'],['口语已学',(snap?.oral?.seen||[]).length,'条'],['口语收藏',(snap?.oral?.favorites||[]).length,'条'],['口语检验',(snap?.oral?.history||[]).length,'次']];const status=saveFailure?'保存失败，请重试或导出备份':snap?.savedAt?'已保存到本机':'尚无已确认的保存记录';return `<div role="status" aria-live="polite"><b style="color:${saveFailure?'#b75c63':'var(--green)'}">${h(status)}</b><p class="muted tiny">最近成功保存：${snap?.savedAt?h(new Date(snap.savedAt).toLocaleString('zh-CN')):'暂无'}</p></div><div>${rows.map(([label,n,unit])=>`<div class="setting-row"><span>${label}</span><b>${n} ${unit}</b></div>`).join('')}</div><p class="muted tiny">以上为本机实际读取的保存快照。未完成测验不支持断点续答；清除网站数据可能丢失记录。</p>`}
function refreshSavePanel(){const el=document.getElementById('savePanelContent');if(el)el.innerHTML=savePanelContent();const badge=document.getElementById('saveEntryStatus');if(badge)badge.textContent=saveFailure?'保存失败 · 点击查看':(saveSnapshot()?.savedAt?'已保存 · 点击查看':'自动保存 · 点击查看')}
function savePanelView(){return `<button class="quiz-return" data-action="meHome">‹ 返回我的学习</button><h1>自动保存记录</h1><div class="surface" id="savePanelContent">${savePanelContent()}</div><div class="hr-stack" style="margin-top:14px"><button class="primary" data-action="saveNow">立即保存</button><button class="secondary" data-action="meBackup">备份与恢复</button></div><p class="muted tiny">学习操作即时保存，使用中定期补存，切换后台或退出时尝试保存。无需登录，不会自动同步至云端。</p>`}
// Save changed learning data synchronously, including on iOS backgrounding.
let lastSavedPayload=null;
function autosaveProgress(){
 try {
  const {savedAt,...data}=STORE;
  const payload=JSON.stringify(data);
  if(payload===lastSavedPayload && localStorage.getItem(KEY))return true;
  const ok=save();if(ok)lastSavedPayload=payload;return ok;
 }catch(e){return false;}
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)autosaveProgress()});
window.addEventListener('pagehide',autosaveProgress);
document.addEventListener('freeze',autosaveProgress);
setInterval(()=>{if(!document.hidden)autosaveProgress()},15000);
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function prevDay(iso){let [y,m,d]=iso.split('-').map(Number),dt=new Date(y,m-1,d);dt.setDate(dt.getDate()-1);return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`}
function streak(){let day=today();if(!(STORE.days[day]>0))day=prevDay(day);let s=0;while(STORE.days[day]>0){s++;day=prevDay(day)}return s}
function learnedCount(){return Object.values(STORE.words).filter(x=>x.level>=3).length}
function dueCount(){return Object.values(STORE.words).filter(x=>x.seen&&x.due<=Date.now()).length}
function seenCount(){return learnedQuizWords().length}
function favCount(){return Object.values(STORE.words).filter(x=>x.favorite).length}
function todayCount(){const day=today();const fromWords=Object.values(STORE.words).filter(x=>x&&x.lastDay===day).length;return Math.max(fromWords,Number(STORE.days[day])||0)}
function learningSummary(){const goal=Math.max(1,Number(STORE.goal)||8),done=todayCount();return {goal,done,seen:seenCount(),pct:Math.min(100,Math.round(done/goal*100))}}
function entry(id){STORE.words[id]??={level:0,seen:false,favorite:false,due:null};return STORE.words[id]}
function nav(tab){
 speechStop();stopRoleRecognition();
 // Top-right practice button is a reversible page switch. Keep the exact previous page,
 // deck position, card side and scroll offset without resetting the learning state.
 if(tab==='quiz'&&state.tab==='quiz'){
  const origin=state.quizReturn||{tab:'home',scrollY:0,detailId:null};
  state.quizReturn=null;state.tab=origin.tab;state.detailId=origin.detailId||null;
  render();requestAnimationFrame(()=>window.scrollTo({top:origin.scrollY||0,behavior:'auto'}));return;
 }
 if(tab==='quiz'){state.quizReturn={tab:state.tab,scrollY:window.scrollY,detailId:state.detailId};}
 else if(state.tab==='quiz'){state.quizReturn=null;}
 if(tab==='scene'&&state.tab!=='scene')state.sceneId=null;
 state.tab=tab;state.detailId=null;
 if(tab!=='scene')state.sceneId=null;
 if(tab==='me')state.mePanel='';
 if(tab==='study'&&!state.deck.length)startDeck();
 if(tab==='quiz'){state.quizMode='menu';state.quiz=null;}
 render();window.scrollTo(0,0);
}
/** Generate the next flashcard group. `fresh` is used exclusively for "换一组":
 * it prefers new vocabulary and excludes cards from the previous group, even
 * after the daily learning goal has been reached. The daily goal is a target,
 * never a hard limit on studying additional words. */
function startDeck(ids,options={}){
 const limit=Math.max(1,Math.min(20,Number(STORE.goal)||8));
 const fresh=!!options.fresh;
 const date=today();
 if(!STORE.deckRotation||STORE.deckRotation.day!==date||!Array.isArray(STORE.deckRotation.ids)){
  STORE.deckRotation={day:date,ids:[]};
 }
 const history=new Set(STORE.deckRotation.ids);
 const previous=new Set(state.deck);
 let chosen=[];
 if(ids&&ids.length){chosen=ids.slice(0,limit)}
 else if(fresh){
  const unseen=DB.words.filter(w=>!STORE.words[w.id]?.seen&&!(Number(STORE.words[w.id]?.level)>=1));
  const learned=DB.words.filter(w=>!!STORE.words[w.id]?.seen||Number(STORE.words[w.id]?.level)>=1);
  // A new batch must not repeat the current batch when other cards exist.
  // Rotate unstudied words first; use already-studied words only when necessary.
  const buckets=[
   unseen.filter(w=>!previous.has(w.id)&&!history.has(w.id)),
   unseen.filter(w=>!previous.has(w.id)),
   learned.filter(w=>!previous.has(w.id)&&!history.has(w.id)),
   learned.filter(w=>!previous.has(w.id)),
   DB.words.filter(w=>!previous.has(w.id)),
   DB.words
  ];
  const collected=new Set();
  for(const pool of buckets){
   for(const w of pool){
    if(collected.has(w.id))continue;
    collected.add(w.id);chosen.push(w.id);
    if(chosen.length>=limit)break;
   }
   if(chosen.length>=limit)break;
  }
 } else {
  const due=DB.words.filter(w=>{let p=STORE.words[w.id];return p?.seen&&p.due<=Date.now()});
  const unseen=DB.words.filter(w=>!STORE.words[w.id]?.seen);
  const studying=DB.words.filter(w=>STORE.words[w.id]?.seen&&STORE.words[w.id]?.level<3&&!due.includes(w));
  chosen=[...due,...unseen,...studying].slice(0,limit).map(w=>w.id);
  if(!chosen.length)chosen=DB.words.slice(0,limit).map(w=>w.id);
 }
 state.deck=[...new Set(chosen)].slice(0,limit);
 state.deckIndex=0;state.flipped=false;
 // Remember which groups were displayed today so repeated "换一组"
 // keeps advancing, even if the app is closed and reopened.
 STORE.deckRotation.ids=[...new Set([...STORE.deckRotation.ids,...state.deck])].slice(-DB.words.length);
 save();
}
