function meView(){if(state.mePanel==='autosave')return savePanelView();if(['phrases','sentences'].includes(state.mePanel))return notebookView(state.mePanel);const panel=state.mePanel||'', legacy=meLegacyView(), marker='<div class="surface"><h3 style="margin:0 0 7px">学习偏好', split=legacy.indexOf(marker), bottom=legacy.indexOf('<section class="me-bottom-info"');const back='<button class="quiz-return" data-action="meHome">‹ 返回我的学习</button>';const cards=(words)=>words.map(w=>`<button class="hr-entry" data-detail="${h(w.id)}"><span><b>${h(w.term)}</b><small>${h(w.zh)}</small></span>${icon('right','sm')}</button>`).join('')||'<div class="surface">暂无记录</div>';if(panel==='settings')return back+'<h1>学习设置</h1>'+legacy.slice(split,bottom).replace(/<\/div>\s*$/,'');if(panel==='version')return back+legacy.slice(bottom);if(panel==='history')return back+'<h1>学习记录</h1><div class="surface">'+(Object.entries(STORE.days).sort((a,b)=>b[0].localeCompare(a[0])).map(([d,n])=>`<div class="setting-row"><b>${h(d)}</b><span>${h(n)} 个词汇</span></div>`).join('')||'暂无学习记录')+'</div>';if(panel==='wrong')return back+'<h1>错题记录</h1><div class="hr-stack">'+cards(wrongWords())+(wrongWords().length?'<button class="primary" data-action="meWrongQuiz">开始错题复习</button>':'')+'</div>';if(panel==='learned'||panel==='favorites')return back+'<h1>'+(panel==='learned'?'已学习词汇':'我的收藏')+'</h1><div class="hr-stack">'+cards(panel==='learned'?learnedQuizWords():DB.words.filter(w=>STORE.words[w.id]?.favorite))+'</div>';if(panel==='results')return back+'<h1>练习记录</h1><div class="surface">'+((STORE.quizHistory||[]).slice().reverse().map(r=>`<div class="setting-row"><span>${h(r.label)}<br><small>${h(r.date)}</small></span><b>${r.correct}/${r.total}</b></div>`).join('')||'暂无练习记录')+'</div>';if(panel==='backup')return back+`<h1>数据备份与迁移</h1><div class="surface hr-stack"><p>记录保存在本机，恢复会覆盖当前记录。</p><button class="secondary" data-action="export">导出 JSON</button><button class="secondary" data-action="importFile">导入 JSON</button><button class="secondary" data-action="syncModal">迁移码</button><input type="file" id="progressUpload" class="sr-only" accept="application/json,.json"></div>`;return legacy.slice(0,split)+'</div><h2>我的学习</h2><div class="hr-stack">'+'<button class="hr-entry" data-nav="oral">高频职场口语 ›</button>'+hrCard('meLearned','book','已学习词汇',`${seenCount()} 个词汇`)+hrCard('meFavorites','heart','我的收藏',`${favCount()} 个词汇`)+hrCard('book:phrases','book','我的短语本',`${bookIds('phrases').length} 条收藏`)+hrCard('book:sentences','book','我的句子本',`${bookIds('sentences').length} 条收藏`)+hrCard('meWrong','repeat','错题记录',`${wrongWords().length} 个待巩固词汇`)+hrCard('meHistory','book','学习记录','每日学习足迹')+hrCard('meResults','trophy','练习记录','历史测验成绩')+hrCard('meBackup','download','数据备份与迁移','导出、导入或迁移码')+hrCard('meSettings','user','设置','学习目标、语速、主题')+hrCard('meVersion','repeat','版本与更新','检查或手动刷新')+hrCard('meAutosave','check','自动保存记录',`<span id="saveEntryStatus">${saveFailure?'保存失败 · 点击查看':saveSnapshot()?.savedAt?'已保存 · 点击查看':'自动保存 · 点击查看'}</span>`)+'</div>'}

function detailView(){if(!state.detailId)return '';let w=byId(state.detailId);if(!w)return '';let e=STORE.words[w.id]||{};let tabs=[['meaning','核心释义'],['dialogue','职场对话'],['expand','拓展延伸'],['practice','练一练']];let alt=DB.words.filter(x=>x.moduleId===w.moduleId&&x.id!==w.id&&x.zh!==w.zh).slice(0,3),choices=[w,...alt].sort((a,b)=>hashText(a.id+w.id)%1000-hashText(b.id+w.id)%1000);let body={meaning:`<span class="tag green">专业解释</span><h3>在 HR 场景中是什么意思？</h3><p>${h(w.definition)}</p>${w.usage?`<div class="usage-note"><b>HR 实际用法</b><div>${h(w.usage)}</div></div>`:''}${w.distinction?`<div class="distinguish-note"><b>容易混淆 · 专业辨析</b><div>${h(w.distinction)}</div></div>`:''}<h3>常用短语 · 中英对照</h3>${phraseView(w)}${bookButton(w,"phrases")}<h3>职场英文例句 · 中英对照</h3><div class="quote example-card"><div class="example-en">${h(w.example)}</div><div class="example-zh"><span class="example-label">中文翻译</span><span>${h(w.exampleZh||'')}</span></div><button class="bubble-action" data-say="${h(w.example)}">${icon('sound','sm')} 朗读这句话</button>${bookButton(w,"sentences")}</div>`,dialogue:`<p class="muted">真实 HR 语境中的两人对话，点击每一句可听发音。</p>${w.dialogue.map((l,i)=>`<div class="quote" style="border-color:${i?'#28ac8b':'var(--violet)'}"><b style="font-size:12px">${h(l.role)}</b><p>${h(l.en)}</p>${l.zh?`<p class="dialogue-zh">${h(l.zh)}</p>`:""}<button class="bubble-action" data-say="${h(l.en)}">${icon('sound','sm')} 播放这句</button></div>`).join('')}`,expand:`<h3>高频搭配</h3><div class="ext-list"><div class="ext-item"><b>${h(w.collocation||w.term)}</b><p class="phrase-zh">${h(w.collocationZh||w.zh)}</p><button class="bubble-action" data-say="${h(w.collocation||w.term)}">${icon('sound','sm')} 听搭配发音</button>${bookButton(w,"phrases")}</div></div>${w.aliases&&w.aliases.length?`<h3>常见写法／搜索别称</h3><p class="aliases">${w.aliases.map(h).join(' · ')}</p>`:''}${w.distinction?`<div class="distinguish-note"><b>相近术语辨析</b><div>${h(w.distinction)}</div></div>`:''}<h3>同主题延伸词汇</h3>${alt.map(x=>`<button class="task-item" data-detail="${h(x.id)}"><span style="flex:1"><b>${h(x.term)}</b><small>${h(x.zh)}</small></span>${icon('right','sm')}</button>`).join('')}<p class="muted tiny">延伸推荐来自相同 HR 专业模块。</p>`,practice:`<h3>请选择最准确的中文释义</h3><div class="quiz-options">${choices.map(c=>`<button class="quiz-option ${state.detailChoice!==null?(c.id===w.id?'correct':state.detailChoice===c.id?'wrong':''):''}" data-detail-answer="${h(c.id)}"><span>${h(c.zh)}</span></button>`).join('')}</div>${state.detailChoice!==null?`<div class="quiz-explain">${state.detailChoice===w.id?'回答正确！':'正确答案：'+h(w.zh)}<br>${h(w.example)}<br><span class="example-side-zh">${h(w.exampleZh||'')}</span></div>`:''}`}[state.detailTab]||'';return `<div class="overlay" data-action="closeOverlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="词条详情：${h(w.term)}"><div class="sheet-handle"></div><div class="sheet-head"><span class="tag lav">${h(modById(w.moduleId)?.title)}</span><button class="iconbtn" data-action="closeDetail" aria-label="关闭详情">${icon('close')}</button></div><h2>${h(w.term)}</h2><div class="sheet-zh">${h(w.zh)}</div>${ipaView(w,true)}<div style="display:flex;gap:10px;margin-top:15px"><button class="listen" data-play-word="${h(w.id)}">${icon('sound','sm')} 设备英语朗读 ${Number(STORE.rate)===1?'1.0':STORE.rate}×</button><button class="listen fav-action ${e.favorite?'active':''}" data-fav="${h(w.id)}" aria-pressed="${!!e.favorite}">${icon('heart','sm')} ${e.favorite?'已收藏':'收藏'}</button></div><nav class="sheet-tabbar" aria-label="词条内容切换">${tabs.map(([id,label])=>`<button class="sheet-tab ${state.detailTab===id?'active':''}" data-detail-tab="${id}">${label}</button>`).join('')}</nav><div class="sheet-section">${body}</div><div class="sheet-footer"><button class="secondary" data-action="detailNext">下一个词条 ${icon('right','sm')}</button><button class="primary" data-action="learnThis">用卡片练习 ${icon('layers','sm')}</button></div></section></div>`}

function portableProgress(){return {version:8,exported:new Date().toISOString(),progress:{...STORE}}}
function validProgress(p){return p&&typeof p==='object'&&p.words&&typeof p.words==='object'&&!Array.isArray(p.words)&&p.days&&typeof p.days==='object'&&Number.isFinite(Number(p.xp||0))}
function applyBackup(parsed){const previousStore=STORE;let progress=parsed&&parsed.progress?parsed.progress:parsed;if(!validProgress(progress))throw Error('备份格式不正确');let safeWords={};for(const [id,item] of Object.entries(progress.words)){if(!byId(id)||!item||typeof item!=='object')continue;safeWords[id]={level:Math.max(0,Math.min(5,Number(item.level)||0)),seen:!!item.seen,favorite:!!item.favorite,due:Number.isFinite(+item.due)?+item.due:null,last:Number.isFinite(+item.last)?+item.last:null,lastDay:typeof item.lastDay==='string'?item.lastDay:null};}let safeDays={};for(const [date,n] of Object.entries(progress.days)){if(/^\d{4}-\d{2}-\d{2}$/.test(date))safeDays[date]=Math.max(0,Math.min(1000,Number(n)||0))}STORE={oral:cleanOral(progress.oral),phrases:safeBook(progress.phrases),sentences:safeBook(progress.sentences),wrong:Object.fromEntries(Object.entries(progress.wrong||{}).filter(([id,n])=>byId(id)&&Number(n)>0).map(([id,n])=>[id,Math.min(9999,Number(n))])),quizHistory:Array.isArray(progress.quizHistory)?progress.quizHistory.filter(r=>r&&typeof r.date==='string'&&typeof r.label==='string'&&Number.isFinite(r.correct)&&Number.isFinite(r.total)).slice(-200):[],words:safeWords,days:safeDays,roleplays:Object.fromEntries(Object.entries(progress.roleplays||{}).filter(([key,val])=>/^S\d{2}-\d{4}-\d{2}-\d{2}$/.test(key)&&val&&typeof val==='object').slice(0,200)),xp:Math.max(0,Number(progress.xp)||0),dark:!!progress.dark,goal:[5,8,10,15,20].includes(+progress.goal)?+progress.goal:8,rate:[.75,.9,1,1.15].includes(+progress.rate)?+progress.rate:1};if(!save()){STORE=previousStore;throw Error('无法写入本地存储，原有学习记录未被覆盖')}state.deck=[];state.quiz=null;state.syncOpen=false;nav('me');toast('已恢复 '+Object.keys(safeWords).length+' 个词条的学习数据')}
function bytesTo64(bytes){let binary='';for(let i=0;i<bytes.length;i+=8192){binary+=String.fromCharCode(...bytes.subarray(i,i+8192))}return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function b64ToBytes(s){s=s.replace(/-/g,'+').replace(/_/g,'/');let b=atob(s);return Uint8Array.from(b,c=>c.charCodeAt(0))}
async function generateTransferCode(){let raw=new TextEncoder().encode(JSON.stringify(portableProgress())),bytes=raw,prefix='HRF8-RAW-';if(typeof CompressionStream==='function'){let cs=new CompressionStream('gzip');let writer=cs.writable.getWriter();let result=new Response(cs.readable).arrayBuffer();await writer.write(raw);await writer.close();bytes=new Uint8Array(await result);prefix='HRF8-GZ-'}return prefix+bytesTo64(bytes)}
async function readTransferCode(code){let c=code.replace(/\s+/g,'');let zipped=c.startsWith('HRF8-GZ-');let uncompressed=c.startsWith('HRF8-RAW-');if(!zipped&&!uncompressed)throw Error('不是支持的 HR Fluent V8 迁移码');let bytes=b64ToBytes(c.slice(zipped?8:9));if(bytes.length>400000)throw Error('迁移码过大');if(zipped){if(typeof DecompressionStream!=='function')throw Error('当前浏览器不支持解压迁移码，请改用 JSON 文件备份');let ds=new DecompressionStream('gzip');let writer=ds.writable.getWriter();let result=new Response(ds.readable).arrayBuffer();await writer.write(bytes);await writer.close();bytes=new Uint8Array(await result);}return JSON.parse(new TextDecoder().decode(bytes))}
function syncView(){if(!state.syncOpen)return '';return `<div class="overlay sync-overlay"><section class="sheet sync-sheet" role="dialog" aria-modal="true" aria-label="学习进度迁移"><div class="sheet-handle"></div><div class="sheet-head"><span class="tag lav">${icon('repeat','sm')} 学习进度迁移</span><button class="iconbtn" data-action="closeSync" aria-label="关闭">${icon('close')}</button></div><h2>把学习记录带到新设备</h2><p class="muted">免手机号：把当前完整进度编码成一段可复制文字。新设备在同一知识库的「我的 → 迁移码」粘贴并恢复。该码不是六位数登录密码，也不是云账号；含有学习数据，勿公开。</p><div class="sync-block"><b>① 在旧设备生成迁移码</b><div class="sync-buttons"><button class="primary" data-action="generateCode">生成迁移码</button><button class="secondary" data-action="copyCode">复制</button></div><textarea id="generatedCode" rows="4" readonly placeholder="点击生成迁移码…" aria-label="生成的迁移码"></textarea><p class="tiny muted">一次性生成的是完整进度快照；后续继续学习后需重新生成新码。</p></div><div class="sync-block"><b>② 在新设备粘贴并恢复</b><textarea id="restoreCode" rows="4" placeholder="将旧设备复制的 HRF8-… 迁移码粘贴到这里" aria-label="粘贴迁移码"></textarea><button class="secondary" data-action="restoreCode">恢复学习记录</button><p class="tiny muted">恢复将覆盖此设备现有进度。短信验证码/短登录码自动同步必须接入服务端、数据存储和短信/身份验证服务；本离线版不具备这些能力。</p></div></section></div>`}
function bookmarkView(){if(!state.bookmarkOpen)return '';let host=location.protocol==='https:'&&!/chatgpt|openai|sandbox|127\.0\.0\.1|localhost/i.test(location.hostname);return `<div class="overlay bookmark-overlay"><section class="sheet sync-sheet" role="dialog" aria-modal="true" aria-label="保存知识库入口"><div class="sheet-head"><span class="tag lav">${icon('star','sm')} 便捷访问</span><button class="iconbtn" data-action="closeBookmark" aria-label="关闭">${icon('close')}</button></div><h2>随时打开 HR Fluent</h2><div class="bookmark-tip"><b>iPhone Safari</b><p>打开已部署的 HTTPS 网页 → 点击 Safari 底部「分享」 → 选择「添加书签」或「添加到主屏幕」。</p><b>电脑浏览器</b><p>Chrome / Safari 按 Ctrl+D 或 ⌘D 添加书签。</p></div><div class="sync-block"><b>当前页面地址</b><input id="bookmarkURL" readonly value="${h(location.href)}" aria-label="当前地址"><button class="secondary" data-action="copyURL">复制当前地址</button>${host?'<p class="good-note">✓ 当前是 HTTPS 网页，可将此链接保存为书签。</p>':'<p class="warning-note">当前是文件预览 / 临时链接，可能无法长期访问。请先把本 ZIP 的 index.html 等文件部署到固定 HTTPS 站点，之后再收藏正式网址。</p>'}</div></section></div>`}
async function copyText(s,field){try{await navigator.clipboard.writeText(s);toast('已复制到剪贴板')}catch(e){field?.focus();field?.select();toast('请长按文本选择「复制」')}}

function render(){
 document.body.classList.toggle('dark',!!STORE.dark);
 let view={home:homeView,study:studyView,words:wordsView,scene:sceneView,oral:oralView,quiz:quizView,me:meView}[state.tab]||homeView;
 document.getElementById('root').innerHTML=shell(view())+detailView()+syncView()+bookmarkView();
 if(state.detailId||state.syncOpen||state.bookmarkOpen)document.body.style.overflow='hidden';else document.body.style.overflow='';
 document.querySelectorAll('.sheet').forEach(sheet=>{let b=document.createElement('button');b.className='sheet-scroll-top';b.dataset.action='goTop';b.type='button';b.innerHTML=icon('up','sm')+' 顶部';b.setAttribute('aria-label','返回弹窗顶部');sheet.append(b);sheet.addEventListener('scroll',()=>b.classList.toggle('visible',sheet.scrollTop>180),{passive:true})});
 updateScrollTop();updateScenePlayerUI();
 const statusTabs=document.getElementById('wordStatusFilters');
 if(statusTabs && statusTabs.scrollWidth>statusTabs.clientWidth+3){
  const current=statusTabs.querySelector('.legend-filter.is-active');
  if(current){statusTabs.scrollLeft=Math.max(0,current.offsetLeft-statusTabs.offsetLeft-8)}
 }
}
function updateScrollTop(){const b=document.getElementById('globalScrollTop');if(b)b.classList.toggle('visible',window.scrollY>260)}

function setModule(id){state.module=id;state.query='';state.filter='all';state.visible=24;state.tab='words';render();window.scrollTo(0,0)}
function openDetail(id){state.detailId=id;state.detailTab='meaning';state.detailChoice=null;render()}
window.addEventListener('scroll',updateScrollTop,{passive:true});
let lastSwipe=0;function handleAction(action,btn,ev){if(extraAction(action))return;if(action.startsWith('quizModule:')){let id=action.split(':')[1];launchScopedQuiz(DB.words.filter(w=>w.moduleId===id),modById(id)?.title||'模块测验');return}if(action.startsWith('quizRange:')){let k=action.split(':')[1];launchScopedQuiz(k==='learned'?learnedQuizWords():k==='favorites'?DB.words.filter(w=>STORE.words[w.id]?.favorite):DB.words,({all:'全部词汇',learned:'已学习词汇',favorites:'收藏词汇'})[k]);return}switch(action){case'quizMenu':state.quizMode='menu';state.quiz=null;render();break;case'quizModules':state.quizMode='modules';render();break;case'quizRanges':state.quizMode='ranges';render();break;case'quizMistakes':launchScopedQuiz(wrongWords(),'错题复习');break;case'quizCustom':{let ids=[...document.querySelectorAll('[name=hrModule]:checked')].map(x=>x.value);launchScopedQuiz(DB.words.filter(w=>ids.includes(w.moduleId)),'自定义模块');break}case'meHome':state.mePanel='';render();window.scrollTo(0,0);break;case'meHistory':case'meWrong':case'meBackup':case'meSettings':case'meVersion':case'meLearned':case'meFavorites':case'meResults':state.mePanel=action.slice(2).toLowerCase();render();window.scrollTo(0,0);break;case'meWrongQuiz':nav('quiz');launchScopedQuiz(wrongWords(),'错题复习');break;case'saveNow':{const ok=save();render();if(ok)toast('学习记录已保存到本机');break;}
case'importFile':document.getElementById('progressUpload')?.click();break;
case'syncModal':state.syncOpen=true;state.bookmarkOpen=false;render();break;
case'closeSync':state.syncOpen=false;render();break;
case'bookmarkGuide':state.bookmarkOpen=true;state.syncOpen=false;render();break;case'checkVersion':if(typeof window.hrFluentCheckVersion==='function')window.hrFluentCheckVersion(true);else toast('当前无法检查新版本');break;case'forceUpdate':if(typeof window.hrFluentForceRefresh==='function')window.hrFluentForceRefresh();else toast('请通过 HTTPS 网站尝试刷新');break;case'goTop':{const sheet=btn.closest('.sheet');if(sheet)sheet.scrollTo({top:0,behavior:'smooth'});else window.scrollTo({top:0,behavior:'smooth'});break;}
case'closeBookmark':state.bookmarkOpen=false;render();break;
case'copyURL':copyText(location.href,document.getElementById('bookmarkURL'));break;
case'generateCode':generateTransferCode().then(code=>{let el=document.getElementById('generatedCode');if(el){el.value=code;toast('迁移码已生成，请复制保存')}}).catch(e=>toast('生成失败：'+e.message));break;
case'copyCode':{let el=document.getElementById('generatedCode');if(!el?.value){toast('请先生成迁移码');break}copyText(el.value,el);break}
case'restoreCode':{let value=document.getElementById('restoreCode')?.value||'';if(!value.trim()){toast('请先粘贴迁移码');break}if(!confirm('恢复迁移码将覆盖此设备现有的学习记录，确定继续吗？'))break;readTransferCode(value).then(applyBackup).catch(e=>toast('恢复失败：'+e.message));break}
case'backFromQuiz':nav('quiz');break;case'continue':startDeck();nav('study');break;case'showAdded':state.query='';state.module='all';state.filter='added';state.visible=24;nav('words');break;case'flip':if(Date.now()-lastSwipe<350)break;state.flipped=!state.flipped;render();break;case'prev':if(state.deckIndex>0){state.deckIndex--;state.flipped=false;render()}break;case'next':if(state.deckIndex<state.deck.length-1){state.deckIndex++;state.flipped=false;render()}break;case'reshuffle':{const previous=state.deck.join('|');startDeck(null,{fresh:true});render();toast(state.deck.join('|')===previous?'当前词库已全部轮换，可继续复习':'已切换新词组 · 今日达标也能继续学习');break;}case'more':state.visible+=24;render();break;case'clearFilters':state.query='';state.module='all';state.filter='all';state.visible=24;render();break;case'listToDeck':{let a=filteredWords().slice(0,Math.max(1,Number(STORE.goal)||8)).map(w=>w.id);if(a.length===0){toast('当前没有可学习的词汇');break}startDeck(a);nav('study');break}case'backScenes':speechStop();stopRoleRecognition();state.sceneId=null;state.roleplay=false;state.sceneAnswer=false;render();break;
case'stopScene':stopScenePlayback();break;
case'toggleRoleplay':{const sc=DB.scenarios.find(x=>x.id===state.sceneId);if(!sc)break;if(!state.roleplay)startRoleplay(sc);else{stopRoleRecognition();state.roleplay=false}render();break}
case'roleRestart':{const sc=DB.scenarios.find(x=>x.id===state.sceneId);if(sc)startRoleplay(sc);render();break}
case'roleMic':startRoleMic();break;
case'roleCheck':checkRoleAnswer();break;
case'roleReference':state.roleReference=!state.roleReference;render();break;
case'roleNext':advanceRoleplay();break;
case'toggleSceneZh':state.sceneZh=!state.sceneZh;render();break;case'sceneAnswer':state.sceneAnswer=!state.sceneAnswer;render();break;case'newQuiz':startQuiz();render();break;case'nextQuestion':{let q=state.quiz,item=q.items[q.index];if(!item||item.chosen===null)return;if(q.index<q.items.length-1){q.index++}else{q.done=true;if(!q.credited){let n=q.items.filter(i=>i.chosen===i.wordId).length;STORE.xp+=n*5;q.credited=true;STORE.quizHistory??=[];STORE.quizHistory.push({date:new Date().toISOString().slice(0,10),label:state.quizLabel||'测验',correct:n,total:q.items.length});STORE.quizHistory=STORE.quizHistory.slice(-200);save()}}render();break}case'reviewWrong':{let ids=state.quiz.items.filter(i=>i.chosen!==i.wordId).map(i=>i.wordId);startDeck(ids);nav('study');break}case'closeDetail':state.detailId=null;render();break;case'closeOverlay':if(ev.target===btn&&btn.classList.contains('overlay')){state.detailId=null;render()}break;case'detailNext':{let n=DB.words.findIndex(w=>w.id===state.detailId),w=DB.words[(n+1)%DB.words.length];openDetail(w.id);break}case'learnThis':{let w=byId(state.detailId),others=DB.words.filter(x=>x.moduleId===w.moduleId&&x.id!==w.id).slice(0,19);startDeck([w.id,...others.map(x=>x.id)]);nav('study');break}case'dark':STORE.dark=!STORE.dark;save();render();break;case'export':{let blob=new Blob([JSON.stringify({version:8,exported:new Date().toISOString(),progress:STORE},null,2)],{type:'application/json'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hr-fluent-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习记录已导出');break}case'reset':if(confirm('确定清空当前设备的学习进度、收藏和积分吗？此操作不可撤销。')){STORE={words:{},days:{},xp:0,dark:STORE.dark,goal:STORE.goal,rate:STORE.rate,quizSource:STORE.quizSource,v15SpeedMigration:true};save();state.deck=[];render();toast('学习记录已清空')}break;case'streak':toast(`已连续学习 ${streak()} 天，今日完成 ${todayCount()} 个单词`);break;}}
document.addEventListener('click',ev=>{let b=ev.target.closest('button,[data-action="flip"],.overlay');if(!b)return;if(b.dataset.playAccent){ev.stopPropagation();speakAccent(b.dataset.wordId,b.dataset.playAccent);return}if(b.dataset.playWord){ev.stopPropagation();playWord(b.dataset.playWord);return}if(b.dataset.playScene){ev.stopPropagation();playScene(b.dataset.playScene);return}if(b.dataset.say){ev.stopPropagation();speechStop();tts(b.dataset.say);return}if(b.dataset.nav){nav(b.dataset.nav);return}if(b.dataset.quizSource){const source=b.dataset.quizSource;if(source==='all'||source==='learned'){if(source!==state.quizSource){state.quizSource=source;STORE.quizSource=source;save();startQuiz();render();window.scrollTo({top:0,behavior:'auto'})}}return}if(b.dataset.module){setModule(b.dataset.module);return}
if(b.dataset.statusFilter){
 const selected=b.dataset.statusFilter;
 const previousHorizontalScroll=b.closest('#wordStatusFilters')?.scrollLeft||0;
 state.filter=state.filter===selected?'all':selected;
 state.visible=24;
 render();
 // The list is re-rendered on filter changes; keep the tapped tab in view.
 const filters=document.getElementById('wordStatusFilters');
 if(filters){
  filters.scrollLeft=previousHorizontalScroll;
  const selectedButton=filters.querySelector('[data-status-filter="'+state.filter+'"]');
  if(selectedButton){
   const start=selectedButton.offsetLeft-filters.offsetLeft;
   const end=start+selectedButton.offsetWidth;
   if(start<filters.scrollLeft)filters.scrollLeft=start-4;
   else if(end>filters.scrollLeft+filters.clientWidth)filters.scrollLeft=end-filters.clientWidth+4;
  }
  const box=filters.getBoundingClientRect();
  if(box.top<0||box.bottom>window.innerHeight-95)filters.scrollIntoView({block:'start',behavior:'instant'});
 }
 return;
}
if(b.dataset.moduleFilter){state.module=b.dataset.moduleFilter;state.visible=24;render();return}if(b.dataset.rate){rateWord(b.dataset.rate==='1');return}if(b.dataset.scene){speechStop();stopRoleRecognition();state.sceneId=b.dataset.scene;state.roleplay=false;state.sceneAnswer=false;state.sceneReveal=1;state.sceneZh=true;render();window.scrollTo(0,0);return}if(b.dataset.roleSelect){const sc=DB.scenarios.find(x=>x.id===state.sceneId);if(sc&&state.roleplay&&state.roleplayRole!==b.dataset.roleSelect){stopRoleRecognition();state.roleplayRole=b.dataset.roleSelect;state.roleplayStep=0;state.roleInput='';state.roleFeedback=null;state.roleReference=false;state.roleplayAnswers={};render()}return}if(b.dataset.detail){openDetail(b.dataset.detail);return}if(b.dataset.fav){ev.stopPropagation();let e=entry(b.dataset.fav);e.favorite=!e.favorite;save();render();toast(e.favorite?'已加入收藏':'已取消收藏');return}if(b.dataset.detailTab){state.detailTab=b.dataset.detailTab;state.detailChoice=null;render();return}if(b.dataset.detailAnswer){state.detailChoice=b.dataset.detailAnswer;render();return}if(b.dataset.answer){const q=state.quiz,i=q.items[q.index];if(i.chosen!==null)return;i.chosen=b.dataset.answer;STORE.wrong??={};if(i.chosen!==i.wordId)STORE.wrong[i.wordId]=(Number(STORE.wrong[i.wordId])||0)+1;else if(state.quizLabel==='错题复习')delete STORE.wrong[i.wordId];save();render();return}if(b.dataset.action){ev.stopPropagation();handleAction(b.dataset.action,b,ev)}});
document.addEventListener('input',ev=>{if(ev.target.id==='roleAnswer'){state.roleInput=ev.target.value;return}if(ev.target.id==='wordSearch'){state.query=ev.target.value;state.visible=24;let temp=document.createElement('div');temp.innerHTML=wordsView();let res=temp.querySelector('#wordResults');let old=document.querySelector('#wordResults');if(old&&res)old.innerHTML=res.innerHTML;}});
document.addEventListener('change',ev=>{if(ev.target.id==='wordFilter'){state.filter=ev.target.value;state.visible=24;render()}if(ev.target.id==='voiceRate'){STORE.rate=Number(ev.target.value);STORE.v15SpeedMigration=true;save();render();toast('朗读速度：'+STORE.rate+'×')}if(ev.target.id==='dailyGoal'){STORE.goal=Number(ev.target.value);state.deck=[];save();render();toast('每日目标已更新；下一组卡片将按新目标生成')}});
document.addEventListener('change',ev=>{if(ev.target?.id!=='progressUpload')return;let f=ev.target.files?.[0];if(!f)return;if(f.size>800000){toast('备份文件过大，无法导入');return}f.text().then(s=>{let parsed=JSON.parse(s);if(confirm('即将用备份覆盖当前学习记录，确定恢复吗？'))applyBackup(parsed)}).catch(e=>toast('导入失败：'+e.message));ev.target.value='';});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&state.syncOpen){state.syncOpen=false;render();return}if(ev.key==='Escape'&&state.bookmarkOpen){state.bookmarkOpen=false;render();return}if(ev.key==='Escape'&&state.detailId){state.detailId=null;render();return}if(ev.target.matches('input,select'))return;if(state.tab==='study'&&!state.detailId){if(ev.code==='Space'){ev.preventDefault();state.flipped=!state.flipped;render()}else if(ev.key==='ArrowLeft'&&state.deckIndex>0){state.deckIndex--;state.flipped=false;render()}else if(ev.key==='ArrowRight'&&state.deckIndex<state.deck.length-1){state.deckIndex++;state.flipped=false;render()}}});
let swipeX=null;document.addEventListener('touchstart',ev=>{if(ev.target.closest('.tapcard'))swipeX=ev.touches[0].clientX},{passive:true});document.addEventListener('touchend',ev=>{if(swipeX===null)return;let dx=ev.changedTouches[0].clientX-swipeX;swipeX=null;if(Math.abs(dx)<75)return;lastSwipe=Date.now();if(dx<0&&state.deckIndex<state.deck.length-1)state.deckIndex++;if(dx>0&&state.deckIndex>0)state.deckIndex--;state.flipped=false;render();},{passive:true});

function safeBook(a){return Array.isArray(a)?[...new Set(a.filter(id=>typeof id==='string'&&byId(id)))]:[]}
function bookIds(k){return safeBook(STORE[k])}
function bookButton(w,k){let yes=bookIds(k).includes(w.id);return `<button class="secondary" data-action="bookToggle:${k}:${w.id}" aria-pressed="${yes}">${yes?'♥ 已收藏':'♡ 收藏'+(k==='phrases'?'短语':'句子')}</button>`}
function notebookView(k){let phrase=k==='phrases',ids=bookIds(k);return `<button class="quiz-return" data-action="meHome">‹ 返回我的学习</button><h1>${phrase?'我的短语本':'我的句子本'}</h1><p class="muted">独立收藏 · ${ids.length} 条</p><div class="hr-stack">${ids.map(id=>{let w=byId(id),en=phrase?w.collocation:w.example,zh=phrase?w.collocationZh:w.exampleZh;return `<div class="surface"><b>${h(en)}</b><p>${h(zh)}</p><div class="hero-buttons"><button class="listen" data-say="${h(en)}">${icon('sound','sm')} 朗读</button><button class="secondary" data-detail="${id}">原词条</button>${bookButton(w,k)}</div></div>`}).join('')||'<div class="empty">暂无收藏，请在词条详情收藏短语或例句。</div>'}${ids.length?`<button class="primary" data-action="mixedBook:${k}">练习本内内容</button>`:''}</div>`}
const MIX_TYPES={word:'单词释义',phrase:'短语翻译',sentence:'句子理解',listen:'听音辨词'};
function mixFields(w,t){return t==='phrase'?[w.collocation,w.collocationZh]:t==='sentence'?[w.example,w.exampleZh]:[w.term,w.zh]}
function mixPool(scope){return scope==='learned'?learnedQuizWords():scope==='favorites'?DB.words.filter(w=>STORE.words[w.id]?.favorite):scope==='wrong'?wrongWords():scope==='phrases'||scope==='sentences'?bookIds(scope).map(byId):DB.words}
function makeMixed(pool,types){let result=[],used=new Set();for(let i=0;i<10;i++){let found=false;for(let j=0;j<types.length;j++){let t=types[(i+j)%types.length],w=shuffleQuizWords(pool).find(w=>!used.has(w.id)&&mixFields(w,t).every(Boolean));if(!w)continue;let [en,zh]=mixFields(w,t),opts=[zh];for(let other of shuffleQuizWords(DB.words)){let v=mixFields(other,t)[1];if(v&&!opts.includes(v))opts.push(v);if(opts.length===4)break}if(opts.length<2)continue;used.add(w.id);result.push({wordId:w.id,t,en,zh,opts:shuffleQuizWords(opts),chosen:null});found=true;break}if(!found)break}return {items:result,index:0,done:false}}
function mixedView(){let q=state.mixed;let back='<button class="quiz-return" data-action="quizMenu">‹ 返回测验中心</button>';if(!q)return back+`<div class="surface"><h2>组合练习</h2><label>出题范围 <select id="mixScope" class="control">${Object.entries({all:'全部词汇',learned:'已学习词汇',favorites:'收藏词汇',wrong:'错题词汇',phrases:'我的短语本',sentences:'我的句子本'}).map(([k,v])=>`<option value="${k}" ${state.mixScope===k?'selected':''}>${v}</option>`).join('')}</select></label><p>选择一种或多种题型，每轮最多10题。</p>${Object.entries(MIX_TYPES).map(([k,v])=>`<label class="hr-check"><input type="checkbox" name="mixType" value="${k}" ${(state.mixTypes||Object.keys(MIX_TYPES)).includes(k)?'checked':''}> ${v}</label>`).join('')}<button class="primary" data-action="mixedStart">开始练习</button></div>`;let n=q.items.length,correct=q.items.filter(x=>x.chosen===x.zh).length;if(q.done)return back+`<div class="surface"><h2>练习完成 ${correct}/${n}</h2><p>正确率 ${Math.round(correct/n*100)}%</p>${Object.entries(MIX_TYPES).map(([k,v])=>{let a=q.items.filter(x=>x.t===k);return a.length?`<p>${v}：${a.filter(x=>x.chosen===x.zh).length}/${a.length}</p>`:''}).join('')}${q.items.filter(x=>x.chosen!==x.zh).map(x=>`<div class="quote">${h(x.en)}<br>你的答案：${h(x.chosen)}<br>正确答案：${h(x.zh)}</div>`).join('')}<button class="primary" data-action="mixedOpen">再练一轮</button></div>`;let x=q.items[q.index],answered=x.chosen!==null;return back+`<div class="quiz-head"><span>第 ${q.index+1}/${n} 题 · ${MIX_TYPES[x.t]}</span><span>答对 ${correct}</span></div><div class="bar"><span style="width:${100*q.index/n}%"></span></div><div class="quiz-box"><h2 class="quiz-term">${x.t==='listen'&&!answered?'听音选择中文释义':h(x.en)}</h2><button class="listen" data-say="${h(x.en)}">${icon('sound','sm')} 播放美音</button><div class="quiz-options">${x.opts.map((v,i)=>`<button class="quiz-option ${answered?(v===x.zh?'correct':v===x.chosen?'wrong':''):''}" data-action="mixedAnswer:${i}" ${answered?'disabled':''}>${h(v)}</button>`).join('')}</div>${answered?`<div class="quiz-explain">${x.chosen===x.zh?'回答正确':'正确答案：'+h(x.zh)}<br>${h(x.en)}</div><button class="primary" data-action="mixedNext">${q.index===n-1?'查看成绩':'下一题'}</button>`:''}</div>`}
function extraAction(a){if(oralAction(a))return true;if(a==='meAutosave'){state.mePanel='autosave';render();window.scrollTo(0,0);return true}let [op,k,id]=a.split(':');if(op==='bookToggle'){let w=byId(id);if(!w||!['phrases','sentences'].includes(k))return true;let ids=bookIds(k);STORE[k]=ids.includes(id)?ids.filter(x=>x!==id):[...ids,id];save();render();return true}if(op==='book'){state.mePanel=k;render();window.scrollTo(0,0);return true}if(op==='mixedOpen'||op==='mixedBook'){if(op==='mixedBook'){nav('quiz');state.mixScope=k;state.mixTypes=[k==='phrases'?'phrase':'sentence']}else{state.mixScope='all';state.mixTypes=Object.keys(MIX_TYPES)}state.quizMode='mixed';state.mixed=null;render();window.scrollTo(0,0);return true}if(op==='mixedStart'){let scope=document.getElementById('mixScope').value,types=[...document.querySelectorAll('[name=mixType]:checked')].map(x=>x.value);if(!types.length){toast('请选择题型');return true}if(scope==='phrases')types=types.filter(x=>x==='phrase');if(scope==='sentences')types=types.filter(x=>x==='sentence');if(!types.length){toast('请选择与收藏本对应的题型');return true}let q=makeMixed(mixPool(scope),types);if(!q.items.length){toast('当前范围暂无可练习内容');return true}state.mixScope=scope;state.mixTypes=types;state.mixed=q;render();return true}if(op==='mixedAnswer'){let x=state.mixed.items[state.mixed.index];if(x.chosen!==null)return true;x.chosen=x.opts[Number(k)];STORE.wrong??={};if(x.chosen!==x.zh)STORE.wrong[x.wordId]=(Number(STORE.wrong[x.wordId])||0)+1;save();render();return true}if(op==='mixedNext'){let q=state.mixed;if(q.done||q.items[q.index].chosen===null)return true;if(q.index+1<q.items.length)q.index++;else{q.done=true;let n=q.items.filter(x=>x.chosen===x.zh).length;STORE.xp+=n*5;STORE.quizHistory??=[];STORE.quizHistory.push({date:today(),label:'组合练习 · '+state.mixTypes.map(t=>MIX_TYPES[t]).join(' / '),correct:n,total:q.items.length});STORE.quizHistory=STORE.quizHistory.slice(-200);save()}render();return true}return false}

const SPOKEN=[{"id": "SP001", "cat": "会议沟通", "en": "Can I add something here?", "zh": "我可以补充一点吗？"}, {"id": "SP002", "cat": "会议沟通", "en": "Building on that point, I'd like to add one thing.", "zh": "接着刚才的观点，我想补充一点。"}, {"id": "SP003", "cat": "会议沟通", "en": "Sorry to jump in — quick question on the timeline.", "zh": "抱歉打断一下，我想问个关于时间安排的问题。"}, {"id": "SP004", "cat": "会议沟通", "en": "From my perspective, we need more time.", "zh": "在我看来，我们需要更多时间。"}, {"id": "SP005", "cat": "会议沟通", "en": "The data suggests that we need to review our approach.", "zh": "数据显示我们需要重新审视当前做法。"}, {"id": "SP006", "cat": "会议沟通", "en": "I see it a bit differently — here's why.", "zh": "我的看法略有不同，原因如下。"}, {"id": "SP007", "cat": "会议沟通", "en": "Can we park this and move on?", "zh": "我们可以先搁置这个问题，继续下一项吗？"}, {"id": "SP008", "cat": "会议沟通", "en": "What have we decided, and who's responsible for the next step?", "zh": "我们作出了什么决定？谁负责下一步？"}, {"id": "SP009", "cat": "会议沟通", "en": "Just to confirm — we're agreeing to finalize this by Friday?", "zh": "确认一下，我们同意周五前定稿，对吗？"}, {"id": "SP010", "cat": "会议沟通", "en": "Could you say that again? I didn't quite catch it.", "zh": "能再说一遍吗？我刚才没听清。"}, {"id": "SP011", "cat": "会议沟通", "en": "To summarize, we have three action items.", "zh": "总结一下，我们有三项待办事项。"}, {"id": "SP012", "cat": "会议沟通", "en": "Anything else before we wrap up?", "zh": "结束前还有其他事项吗？"}, {"id": "SP013", "cat": "邮件沟通", "en": "I hope this email finds you well.", "zh": "希望你一切顺利。"}, {"id": "SP014", "cat": "邮件沟通", "en": "Thanks for your time on Monday.", "zh": "感谢你周一抽出时间。"}, {"id": "SP015", "cat": "邮件沟通", "en": "Following up on our conversation, I'd like to confirm the next steps.", "zh": "接着我们之前的沟通，我想确认下一步安排。"}, {"id": "SP016", "cat": "邮件沟通", "en": "When you have a moment, could you review this?", "zh": "方便时能否审阅一下？"}, {"id": "SP017", "cat": "邮件沟通", "en": "Could you review the attached document by Friday?", "zh": "能否在周五前审阅附件？"}, {"id": "SP018", "cat": "邮件沟通", "en": "Just bringing this back to the top of your inbox.", "zh": "再次跟进这封邮件，方便你及时看到。"}, {"id": "SP019", "cat": "邮件沟通", "en": "Just following up on the email below — no rush, just want to make sure it didn't get buried.", "zh": "跟进一下下方邮件，不着急，只是想确认它没有被遗漏。"}, {"id": "SP020", "cat": "邮件沟通", "en": "Please be advised that the policy has changed.", "zh": "请注意，政策已调整。"}, {"id": "SP021", "cat": "邮件沟通", "en": "We're writing to inform you of a policy update effective December 1.", "zh": "特此通知，政策更新将于12月1日生效。"}, {"id": "SP022", "cat": "邮件沟通", "en": "Please find the document attached.", "zh": "请查收附件中的文件。"}, {"id": "SP023", "cat": "邮件沟通", "en": "Let me know if you have any questions.", "zh": "如有任何疑问，请告诉我。"}, {"id": "SP024", "cat": "邮件沟通", "en": "Please don't hesitate to reach out if you need anything else.", "zh": "如需其他帮助，请随时联系我。"}, {"id": "SP025", "cat": "邮件沟通", "en": "Thanks in advance for your help.", "zh": "提前感谢你的帮助。"}, {"id": "SP026", "cat": "员工面谈", "en": "What's on your mind this week?", "zh": "这周你有什么想聊的吗？"}, {"id": "SP027", "cat": "员工面谈", "en": "How sustainable does your current workload feel?", "zh": "你觉得目前的工作量能长期维持吗？"}, {"id": "SP028", "cat": "员工面谈", "en": "Anything you want to make sure we cover today?", "zh": "今天有没有你特别希望讨论的事项？"}, {"id": "SP029", "cat": "员工面谈", "en": "One area I'd love to see you develop is stakeholder management.", "zh": "我希望你进一步提升利益相关方管理能力。"}, {"id": "SP030", "cat": "员工面谈", "en": "This didn't quite hit the mark — here's what I was expecting.", "zh": "这次结果没有完全达到预期，我原本的期望是这样的。"}, {"id": "SP031", "cat": "员工面谈", "en": "For the next quarter, the key area to focus on is communication.", "zh": "下季度重点关注沟通能力。"}, {"id": "SP032", "cat": "员工面谈", "en": "We have a budgeted range for this role based on market data.", "zh": "我们根据市场数据为该岗位设定了薪酬预算区间。"}, {"id": "SP033", "cat": "员工面谈", "en": "That's a bit above the range we have for this level — let me describe the full package.", "zh": "这略高于该职级的薪酬区间，我来介绍一下整体薪酬福利方案。"}, {"id": "SP034", "cat": "员工面谈", "en": "I want to flag something that came up in our last meeting.", "zh": "我想提一下上次会议中出现的一个问题。"}, {"id": "SP035", "cat": "员工面谈", "en": "Can we talk about what happened with the project?", "zh": "我们能谈谈这个项目发生的情况吗？"}, {"id": "SP036", "cat": "员工面谈", "en": "Let me play back what I heard.", "zh": "我来复述一下我的理解。"}, {"id": "SP037", "cat": "员工面谈", "en": "What will you take away from this?", "zh": "这次沟通给你带来了什么启发？"}, {"id": "SP038", "cat": "员工面谈", "en": "Is there anything we didn't cover that you want to discuss next time?", "zh": "有没有今天没谈到、你希望下次讨论的事项？"}, {"id": "SP039", "cat": "协作谈判", "en": "I'd love your input on this proposal.", "zh": "我很希望听听你对这份方案的意见。"}, {"id": "SP040", "cat": "协作谈判", "en": "Would you be able to own this piece?", "zh": "你能负责这一部分吗？"}, {"id": "SP041", "cat": "协作谈判", "en": "We're at risk of missing the deadline without this.", "zh": "如果缺少这一项，我们可能无法按期完成。"}, {"id": "SP042", "cat": "协作谈判", "en": "Could you share your feedback by noon?", "zh": "能否在中午前提供反馈？"}, {"id": "SP043", "cat": "协作谈判", "en": "Flagging this as time-sensitive — we need a decision by Friday.", "zh": "提醒一下，这件事时间紧迫，我们需要在周五前作出决定。"}, {"id": "SP044", "cat": "协作谈判", "en": "I'd love to help, but realistically I can't get to this until next week.", "zh": "我很愿意帮忙，但实际要到下周才能处理。"}, {"id": "SP045", "cat": "协作谈判", "en": "What I can do instead is review the draft.", "zh": "作为替代方案，我可以审阅初稿。"}, {"id": "SP046", "cat": "协作谈判", "en": "I'd like to make the case for additional headcount.", "zh": "我想说明增加人员编制的必要性。"}, {"id": "SP047", "cat": "协作谈判", "en": "The estimated annual benefit is X, compared with a cost of Y.", "zh": "预计年度收益为X，成本为Y。"}, {"id": "SP048", "cat": "协作谈判", "en": "I think we're looking at this from two angles — can we find where they overlap?", "zh": "我觉得我们看问题的角度不同，能否找到共同点？"}, {"id": "SP049", "cat": "协作谈判", "en": "Let's park the disagreement and focus on what we can decide today.", "zh": "先搁置分歧，聚焦今天能够决定的事项。"}, {"id": "SP050", "cat": "协作谈判", "en": "Could we put 30 minutes on the calendar for early next month?", "zh": "能否在下月初安排30分钟沟通？"}, {"id": "SP051", "cat": "任务管理", "en": "Could you take charge of drafting the project kick-off memo by this Friday?", "zh": "你能负责在本周五前起草项目启动备忘录吗？"}, {"id": "SP052", "cat": "任务管理", "en": "Let's split this task into three phases to make it more manageable.", "zh": "我们把任务分为三个阶段，以便更好地管理。"}, {"id": "SP053", "cat": "任务管理", "en": "This is a top priority, so please focus on it before handling other routine work.", "zh": "这是优先事项，请先处理它，再处理其他日常工作。"}, {"id": "SP054", "cat": "任务管理", "en": "You'll need to coordinate with the marketing team to get the latest data for your report.", "zh": "你需要与市场团队协调，获取报告所需的最新数据。"}, {"id": "SP055", "cat": "任务管理", "en": "Make sure to check in with me every Wednesday afternoon to update me on the task's progress.", "zh": "请每周三下午与我同步任务进展。"}, {"id": "SP056", "cat": "任务管理", "en": "The key deliverable for this phase is a detailed budget proposal, not just a rough estimate.", "zh": "本阶段的核心交付物是详细预算方案，而不只是粗略估算。"}, {"id": "SP057", "cat": "任务管理", "en": "Keep me posted on any progress or roadblocks.", "zh": "如有进展或阻碍，请随时告诉我。"}, {"id": "SP058", "cat": "任务管理", "en": "We're running behind schedule. I need you to finish this report by the end of today.", "zh": "我们进度落后了，请在今天结束前完成报告。"}, {"id": "SP059", "cat": "任务管理", "en": "Our goal is to increase Q3 sales by 15%. Let's align on the steps.", "zh": "我们的目标是第三季度销售额增长15%，我们来统一执行步骤。"}, {"id": "SP060", "cat": "任务管理", "en": "I'd like you to coordinate with the tech team to align on the new feature requirements.", "zh": "我希望你与技术团队对接，就新功能需求达成一致。"}, {"id": "SP061", "cat": "任务管理", "en": "Please follow up with the suppliers to confirm the delivery timeline, and update the team in our weekly meeting.", "zh": "请跟进供应商确认交付时间，并在周会上同步进展。"}, {"id": "SP062", "cat": "员工激励", "en": "Great job on winning that major client — your hard work really paid off!", "zh": "成功拿下这个重要客户，干得漂亮，你的努力得到了回报！"}, {"id": "SP063", "cat": "员工激励", "en": "Don't be afraid to think outside the box.", "zh": "不要害怕跳出固有思维。"}, {"id": "SP064", "cat": "员工激励", "en": "We support your professional growth and will provide relevant training resources.", "zh": "我们支持你的职业发展，并将提供相关培训资源。"}, {"id": "SP065", "cat": "员工激励", "en": "I'm impressed by how you stepped up to resolve the crisis. Your problem-solving skills are a huge asset to us.", "zh": "你主动解决危机的表现令人印象深刻，你的解决问题能力对团队非常宝贵。"}, {"id": "SP066", "cat": "请假考勤", "en": "I'd like to apply for three days of annual leave from October 16th to 18th for a family trip.", "zh": "我想申请10月16日至18日三天年假，与家人旅行。"}, {"id": "SP067", "cat": "请假考勤", "en": "I'm feeling under the weather this morning — could I take a sick day and work from home tomorrow if needed?", "zh": "我今天早上身体不适，可以请一天病假，并在需要时明天居家办公吗？"}, {"id": "SP068", "cat": "请假考勤", "en": "My child has a parent-teacher meeting next Friday — would it be okay to take half a day of personal leave?", "zh": "下周五孩子学校有家长会，我可以请半天事假吗？"}, {"id": "SP069", "cat": "请假考勤", "en": "I've already asked Sarah to cover my urgent tasks while I'm away, and I'll finish the handover memo by tomorrow.", "zh": "我已请Sarah在我休假期间处理紧急任务，明天前会完成交接备忘录。"}, {"id": "SP070", "cat": "请假考勤", "en": "If there's an emergency, you can reach me by phone, but I hope to take some time off without work interruptions.", "zh": "如有紧急情况可以电话联系我，但我希望休假期间尽量不受工作打扰。"}, {"id": "SP071", "cat": "请假考勤", "en": "How many days of annual leave do I have left this year? I want to plan my vacation accordingly.", "zh": "我今年还剩多少天年假？我想据此安排休假。"}, {"id": "SP072", "cat": "请假考勤", "en": "I'll be offline but will check email for emergencies.", "zh": "我会离线，但会查看紧急邮件。"}, {"id": "SP073", "cat": "会议主持", "en": "Let's kick off today's meeting by going through the agenda — we should wrap up within 45 minutes.", "zh": "我们先过一下今天的会议议程，争取45分钟内结束。"}, {"id": "SP074", "cat": "会议主持", "en": "Each person has five minutes to share their project updates — please stick to the time limit.", "zh": "每人有五分钟分享项目进展，请遵守时间限制。"}, {"id": "SP075", "cat": "会议主持", "en": "Let's move to the roundtable discussion — what are your thoughts on the new client service policy?", "zh": "进入圆桌讨论环节，大家对新的客户服务政策有什么看法？"}, {"id": "SP076", "cat": "会议主持", "en": "Could someone take notes of the action items we decide on today, along with the owners and deadlines?", "zh": "能否有人记录今天确定的行动事项、负责人和截止日期？"}, {"id": "SP077", "cat": "会议主持", "en": "Before we adjourn, let me do a quick recap of the key points we discussed this morning.", "zh": "散会前，我快速总结一下今天上午讨论的重点。"}, {"id": "SP078", "cat": "会议主持", "en": "If there's no further business, we can end the meeting here — thanks everyone for your active participation.", "zh": "如果没有其他事项，会议到此结束，感谢大家积极参与。"}, {"id": "SP079", "cat": "绩效管理", "en": "Have you finished setting your KPIs for this quarter with your supervisor?", "zh": "你和主管一起确定本季度的关键绩效指标了吗？"}, {"id": "SP080", "cat": "绩效管理", "en": "The annual performance review will take place in December, and everyone needs to prepare a self-assessment report.", "zh": "年度绩效评估将在12月进行，每个人都需要准备自评报告。"}, {"id": "SP081", "cat": "绩效管理", "en": "During the review meeting, we'll discuss your achievements and areas for improvement this year.", "zh": "评估会上我们将讨论你今年的工作成果和待改进之处。"}, {"id": "SP082", "cat": "绩效管理", "en": "My supervisor gave me a good performance rating because I exceeded my sales target by 20%.", "zh": "主管给了我较好的绩效评级，因为我超额完成销售目标20%。"}, {"id": "SP083", "cat": "绩效管理", "en": "Based on your appraisal results, we'll create a personalized career development plan for you.", "zh": "我们将根据评估结果为你制定个性化职业发展计划。"}, {"id": "SP084", "cat": "培训发展", "en": "All new employees are required to complete one week of on-the-job training before working independently.", "zh": "所有新员工在独立工作前须完成一周在岗培训。"}, {"id": "SP085", "cat": "培训发展", "en": "The company will launch a new training program on digital marketing next month.", "zh": "公司下月将推出数字营销培训项目。"}, {"id": "SP086", "cat": "培训发展", "en": "You can take courses on the e-learning platform to improve your presentation skills.", "zh": "你可以在在线学习平台选课，提高演示表达能力。"}, {"id": "SP087", "cat": "培训发展", "en": "Our mentorship program pairs new hires with senior employees for guidance.", "zh": "我们的导师计划为新员工匹配资深员工提供指导。"}, {"id": "SP088", "cat": "培训发展", "en": "I attended a workshop on time management last week, and it was really helpful.", "zh": "我上周参加了时间管理工作坊，非常有帮助。"}, {"id": "SP089", "cat": "培训发展", "en": "The training budget for this year has increased, so we can provide more skill development opportunities.", "zh": "今年培训预算有所增加，因此可以提供更多技能发展机会。"}, {"id": "SP090", "cat": "员工关系", "en": "The company announced a downsizing plan due to the recent economic downturn.", "zh": "由于近期经济下行，公司宣布了人员精简计划。"}, {"id": "SP091", "cat": "招聘薪酬", "en": "We've opened a new position for a marketing specialist.", "zh": "我们新增了一个市场营销专员岗位。"}, {"id": "SP092", "cat": "招聘薪酬", "en": "The compensation for this role includes a competitive base salary and a quarterly performance bonus.", "zh": "该岗位薪酬包括有竞争力的基本工资和季度绩效奖金。"}, {"id": "SP093", "cat": "招聘薪酬", "en": "Our benefits package covers health insurance, dental insurance, and a 401(k) plan.", "zh": "我们的福利包括医疗保险、牙科保险及美国401(k)退休储蓄计划。"}, {"id": "SP094", "cat": "招聘薪酬", "en": "Employees in some senior positions are eligible for stock options after one year of employment.", "zh": "部分高级岗位的员工在任职满一年后具备获得股票期权的资格。"}, {"id": "SP095", "cat": "招聘薪酬", "en": "Could you tell me the salary range for this position before I share my salary expectations?", "zh": "在我说明期望薪资前，能否告知该岗位的薪酬区间？"}, {"id": "SP096", "cat": "招聘薪酬", "en": "The company will cover 80% of the insurance premium for all full-time employees.", "zh": "公司将为所有全职员工承担80%的保险费。"}, {"id": "SP097", "cat": "招聘薪酬", "en": "You'll be eligible for stock options after one year of service.", "zh": "任职满一年后，你将具备获得股票期权的资格。"}, {"id": "SP098", "cat": "招聘薪酬", "en": "The salary adjustment cycle takes place every April.", "zh": "每年4月进行调薪。"}, {"id": "SP099", "cat": "请假考勤", "en": "Our standard working hours are from 9 a.m. to 6 p.m., with an hour for lunch.", "zh": "我们的标准工作时间为上午9点至下午6点，午休一小时。"}, {"id": "SP100", "cat": "请假考勤", "en": "Don't forget to clock in and out every day, otherwise it will affect your attendance record.", "zh": "每天别忘了上下班打卡，否则会影响考勤记录。"}, {"id": "SP101", "cat": "请假考勤", "en": "If you need to work overtime, you have to submit a request to your supervisor in advance.", "zh": "如需加班，须提前向主管提交申请。"}, {"id": "SP102", "cat": "请假考勤", "en": "How many days of paid leave am I entitled to per year as a new employee?", "zh": "作为新员工，我每年有多少天带薪休假？"}, {"id": "SP103", "cat": "请假考勤", "en": "I need to take two days of sick leave next week because I have a doctor's appointment.", "zh": "下周我需要请两天病假，因为预约了就医。"}, {"id": "SP104", "cat": "请假考勤", "en": "Our team offers flexible working hours — you can start work at either 8 a.m. or 9 a.m.", "zh": "团队实行弹性工作时间，可以选择上午8点或9点上班。"}, {"id": "IMG021", "cat": "请假考勤", "en": "Please submit an overtime request before working overtime.", "zh": "加班前请提交加班申请。"}, {"id": "IMG022", "cat": "请假考勤", "en": "All attendance records will be reconciled at the end of the month.", "zh": "所有考勤记录将在月末统一核算。"}, {"id": "IMG023", "cat": "请假考勤", "en": "You can apply for annual leave through our HR system.", "zh": "你可以通过HR系统申请年假。"}, {"id": "IMG024", "cat": "请假考勤", "en": "The shift schedule will be updated every Sunday.", "zh": "倒班排班表每周日更新。"}, {"id": "IMG025", "cat": "请假考勤", "en": "Overtime pay will be included in your monthly paycheck.", "zh": "加班费将随月度工资一同发放。"}, {"id": "IMG026", "cat": "培训发展", "en": "Mandatory safety training is scheduled for this Friday.", "zh": "本周五安排强制性安全培训。"}, {"id": "IMG027", "cat": "培训发展", "en": "This training helps improve cross-cultural communication skills.", "zh": "本次培训有助于提升跨文化沟通能力。"}, {"id": "IMG028", "cat": "培训发展", "en": "We offer internal promotion opportunities for high-performing employees.", "zh": "我们为表现优秀的员工提供内部晋升机会。"}, {"id": "IMG029", "cat": "培训发展", "en": "Your training assessment results will be recorded in your personnel file.", "zh": "培训考核结果将记入你的员工档案。"}, {"id": "IMG030", "cat": "培训发展", "en": "High-potential employees can participate in overseas exchange programs.", "zh": "高潜力员工可参与海外交流项目。"}, {"id": "IMG031", "cat": "员工冲突与调解", "en": "Let's listen to both sides with an open mind.", "zh": "我们不带偏见地听取双方意见。"}, {"id": "IMG032", "cat": "员工冲突与调解", "en": "This misunderstanding was caused by a language barrier.", "zh": "这场误会是由语言障碍造成的。"}, {"id": "IMG033", "cat": "员工冲突与调解", "en": "We'll revise our communication guidelines to prevent similar issues.", "zh": "我们将调整沟通规范，避免类似问题再次发生。"}, {"id": "IMG034", "cat": "员工冲突与调解", "en": "The company will handle disputes in accordance with applicable labor regulations.", "zh": "公司将依据适用的劳动法规处理纠纷。"}, {"id": "IMG035", "cat": "员工冲突与调解", "en": "Both sides need to compromise to reach a solution.", "zh": "双方都需要作出让步，以达成解决方案。"}, {"id": "IMG036", "cat": "离职与工作交接", "en": "Please complete the handover of all your responsibilities within one month.", "zh": "请在一个月内完成全部工作交接。"}, {"id": "IMG037", "cat": "离职与工作交接", "en": "Please return all company equipment and confidential documents.", "zh": "请归还所有公司设备及机密文件。"}, {"id": "IMG038", "cat": "离职与工作交接", "en": "Under this policy, your final pay and any compensation for unused leave will be settled on your last working day, subject to applicable law.", "zh": "根据本政策，在符合适用法律的前提下，最终薪资及未休假期补偿将在最后一个工作日结算。"}, {"id": "IMG039", "cat": "离职与工作交接", "en": "I'll help you with the work visa cancellation process after you resign, if required.", "zh": "离职后，如有需要，我会协助你办理工作签证注销手续。"}, {"id": "IMG040", "cat": "离职与工作交接", "en": "I wish you continued success in your career.", "zh": "祝你未来职业发展顺利。"}, {"id": "IMG041", "cat": "会议主持", "en": "Does anyone have any questions about the agenda?", "zh": "大家对议程有什么疑问吗？"}, {"id": "IMG042", "cat": "会议主持", "en": "Let's move on to the next staffing topic.", "zh": "我们进入下一个人员配置议题。"}, {"id": "IMG043", "cat": "会议主持", "en": "Could you repeat that requirement for me?", "zh": "你能再复述一下这个要求吗？"}, {"id": "IMG044", "cat": "会议主持", "en": "I'll make a note of your suggestion and get back to you later.", "zh": "我会记下你的建议，稍后回复你。"}, {"id": "IMG045", "cat": "会议主持", "en": "This plan needs confirmation from the global HR team at headquarters.", "zh": "该方案需要总部全球HR团队确认。"}, {"id": "IMG046", "cat": "会议主持", "en": "We need to finish this work by the end of the day on Friday.", "zh": "我们需要在周五下班前完成这项工作。"}, {"id": "IMG047", "cat": "会议主持", "en": "I'll send the supplementary materials after this meeting.", "zh": "会后我会补发相关材料。"}, {"id": "IMG048", "cat": "会议主持", "en": "What do you think of this staffing arrangement?", "zh": "你对这项人员安排有什么看法？"}, {"id": "IMG049", "cat": "会议主持", "en": "This adjustment can help reduce employee turnover.", "zh": "这项调整有助于降低员工流失率。"}, {"id": "IMG050", "cat": "会议主持", "en": "Our priority is to maintain a stable workforce on the production floor.", "zh": "我们的首要任务是保持车间人员稳定。"}, {"id": "IMG051", "cat": "编制预算与合规", "en": "The budget for expatriate allowances has been approved.", "zh": "外派员工津贴预算已获批准。"}, {"id": "IMG052", "cat": "编制预算与合规", "en": "We cannot exceed the annual headcount limit.", "zh": "我们不得超出年度人员编制额度。"}, {"id": "IMG053", "cat": "编制预算与合规", "en": "Compliance with labor laws is a top priority in our daily work.", "zh": "劳动用工合规是我们日常工作的重中之重。"}, {"id": "IMG054", "cat": "编制预算与合规", "en": "Any unlawful employment arrangement exposes the company to risk.", "zh": "任何违法用工安排都会给公司带来风险。"}, {"id": "IMG055", "cat": "编制预算与合规", "en": "We'll streamline our recruitment process to fill vacancies more quickly.", "zh": "我们将优化招聘流程，更快填补空缺岗位。"}, {"id": "IMG056", "cat": "编制预算与合规", "en": "The candidate has passed the background check.", "zh": "候选人已通过背景调查。"}, {"id": "IMG057", "cat": "编制预算与合规", "en": "We plan to extend a formal job offer next Monday.", "zh": "我们计划下周一发出正式录用通知。"}, {"id": "IMG058", "cat": "编制预算与合规", "en": "All clauses in the employment contract comply with local laws.", "zh": "劳动合同所有条款均符合当地法律。"}, {"id": "IMG059", "cat": "编制预算与合规", "en": "Confidential information must not be disclosed externally without authorization.", "zh": "未经授权不得向外部披露机密信息。"}, {"id": "IMG060", "cat": "编制预算与合规", "en": "Where legally enforceable, the non-compete restrictions take effect after resignation.", "zh": "在依法可执行的情况下，竞业限制条款于辞职后生效。"}, {"id": "IMG061", "cat": "员工关怀与政策", "en": "Under our internal policy, a work-related injury report must be submitted within 24 hours.", "zh": "根据内部政策，工伤报告须在24小时内提交。"}, {"id": "IMG062", "cat": "员工关怀与政策", "en": "HR will follow up throughout the workers' compensation claims process.", "zh": "HR将全程跟进工伤赔偿申请流程。"}, {"id": "IMG063", "cat": "员工关怀与政策", "en": "You can submit a maternity leave request through our internal system.", "zh": "你可以通过内部系统提交产假申请。"}, {"id": "IMG064", "cat": "员工关怀与政策", "en": "Shift allowances will be calculated separately each month.", "zh": "倒班津贴每月单独核算。"}, {"id": "IMG065", "cat": "员工关怀与政策", "en": "Under our company policy, the housing allowance applies to all foreign employees.", "zh": "根据公司政策，住房津贴适用于所有外籍员工。"}, {"id": "IMG066", "cat": "员工关怀与政策", "en": "Please keep your personnel records up to date.", "zh": "请及时更新你的人事档案信息。"}, {"id": "IMG067", "cat": "员工关怀与政策", "en": "We'll organize team-building activities every quarter.", "zh": "我们每季度组织团队建设活动。"}, {"id": "IMG068", "cat": "员工关怀与政策", "en": "The employee satisfaction survey will launch next month.", "zh": "员工满意度调研将于下月启动。"}, {"id": "IMG069", "cat": "员工关怀与政策", "en": "Departments with low satisfaction scores will implement targeted improvements.", "zh": "满意度得分偏低的部门将开展针对性改进。"}, {"id": "IMG070", "cat": "员工关怀与政策", "en": "We need to improve the efficiency of cross-departmental communication.", "zh": "我们需要提升跨部门沟通效率。"}, {"id": "IMG071", "cat": "安全管理与双语沟通", "en": "I apologize for submitting the report late.", "zh": "对于报告提交延迟，我深表歉意。"}, {"id": "IMG072", "cat": "安全管理与双语沟通", "en": "I'll correct the error and resend the file immediately.", "zh": "我会修正错误并立即重新发送文件。"}, {"id": "IMG073", "cat": "安全管理与双语沟通", "en": "This operating standard applies to all production floor employees.", "zh": "这套操作标准适用于所有车间员工。"}, {"id": "IMG074", "cat": "安全管理与双语沟通", "en": "Foreign engineers must follow the same local factory rules.", "zh": "外籍工程师同样必须遵守当地工厂规章制度。"}, {"id": "IMG075", "cat": "安全管理与双语沟通", "en": "Required personal protective equipment must be worn during production operations.", "zh": "生产作业期间必须佩戴规定的个人防护装备。"}, {"id": "IMG076", "cat": "安全管理与双语沟通", "en": "Report any safety incident immediately through the designated reporting channels, including HR where required.", "zh": "任何安全事件均须立即通过指定渠道上报，并按要求通知HR。"}, {"id": "IMG077", "cat": "安全管理与双语沟通", "en": "We'll arrange interpretation support for all major training sessions.", "zh": "我们将为所有重要培训安排口译支持。"}, {"id": "IMG078", "cat": "安全管理与双语沟通", "en": "Bilingual operating manuals are available in every workshop office.", "zh": "各车间办公室均备有双语操作手册。"}, {"id": "IMG079", "cat": "安全管理与双语沟通", "en": "A daily ten-minute briefing helps reduce misunderstandings across languages.", "zh": "每日十分钟简报有助于减少跨语言沟通误解。"}, {"id": "IMG080", "cat": "安全管理与双语沟通", "en": "I'm responsible for day-to-day HR services for all expatriate employees.", "zh": "我负责所有外派员工的日常HR服务。"}, {"id": "IMG081", "cat": "HR核心职责陈述", "en": "My role covers the full range of HR functions at our manufacturing site.", "zh": "我的职责涵盖生产基地的全部HR职能。"}, {"id": "IMG082", "cat": "HR核心职责陈述", "en": "I'm familiar with HR systems used by German and American companies.", "zh": "我熟悉德国和美国企业采用的人力资源管理体系。"}, {"id": "IMG083", "cat": "HR核心职责陈述", "en": "I practice business English every day for my cross-border work.", "zh": "为了跨境工作，我每天练习商务英语。"}, {"id": "IMG084", "cat": "HR核心职责陈述", "en": "I can communicate effectively in English during meetings without assistance.", "zh": "我能独立使用英语进行有效的会议沟通。"}, {"id": "IMG085", "cat": "HR核心职责陈述", "en": "Writing HR documents in English is a focus of my daily practice.", "zh": "撰写英文HR文件是我日常练习的重点。"}, {"id": "IMG086", "cat": "HR核心职责陈述", "en": "I can prepare bilingual workforce reports efficiently.", "zh": "我能高效编制双语人力报表。"}, {"id": "IMG087", "cat": "HR核心职责陈述", "en": "I know how to handle administrative procedures for foreign employees.", "zh": "我了解如何办理外籍员工的行政手续。"}, {"id": "IMG088", "cat": "HR核心职责陈述", "en": "Labor law compliance is a long-term focus of my work.", "zh": "劳动法合规是我长期的工作重点。"}, {"id": "IMG089", "cat": "HR核心职责陈述", "en": "I can balance production needs with the employee experience.", "zh": "我能平衡生产需求与员工体验。"}, {"id": "IMG090", "cat": "HR核心职责陈述", "en": "Employee retention is a key performance indicator in my work as an HR business partner.", "zh": "员工保留率是我作为HRBP的一项关键绩效指标。"}, {"id": "IMG091", "cat": "协调审批与支持", "en": "Could you give me a minute to check the relevant files?", "zh": "能否稍等一分钟，让我查阅相关文件？"}, {"id": "IMG092", "cat": "协调审批与支持", "en": "I'll coordinate with the administration team to resolve this issue.", "zh": "我会协调行政团队解决这个问题。"}, {"id": "IMG093", "cat": "协调审批与支持", "en": "The finance department has confirmed the payroll calculation standards.", "zh": "财务部已确认薪资核算标准。"}, {"id": "IMG094", "cat": "协调审批与支持", "en": "The plant manager has signed the approval document.", "zh": "厂长已签署审批文件。"}, {"id": "IMG095", "cat": "协调审批与支持", "en": "The global HR team agrees with our talent development plan.", "zh": "全球HR团队认可我们的人才发展计划。"}, {"id": "IMG096", "cat": "协调审批与支持", "en": "We'll evaluate the effectiveness of the implementation in one month.", "zh": "一个月后我们将评估方案的实施效果。"}, {"id": "IMG097", "cat": "协调审批与支持", "en": "This adjustment plan will take effect next month.", "zh": "本次调整方案将于下月生效。"}, {"id": "IMG098", "cat": "协调审批与支持", "en": "All employees will receive an email notification about the new policy.", "zh": "所有员工都将收到有关新政策的邮件通知。"}, {"id": "IMG099", "cat": "协调审批与支持", "en": "If you run into any difficulties, feel free to reach out to HR at any time.", "zh": "如果遇到困难，欢迎随时联系HR。"}, {"id": "IMG100", "cat": "协调审批与支持", "en": "I'm happy to provide full HR support for your work.", "zh": "我很乐意为你的工作提供全面的HR支持。"}, {"id": "IMG001", "cat": "沟通开场与跟进", "en": "Let's have a quick chat about your performance.", "zh": "我们简单聊一下你的工作表现。"}, {"id": "IMG002", "cat": "沟通开场与跟进", "en": "Thanks for taking time out of your busy schedule.", "zh": "感谢你在百忙之中抽空。"}, {"id": "IMG003", "cat": "沟通开场与跟进", "en": "I'm writing to follow up on the progress.", "zh": "我写这封邮件是为了跟进进展。"}, {"id": "IMG004", "cat": "沟通开场与跟进", "en": "Could you give me a brief update on this matter?", "zh": "你能简单介绍一下这件事的最新进展吗？"}, {"id": "IMG005", "cat": "沟通开场与跟进", "en": "I need to confirm a few details with you.", "zh": "我需要和你确认几个细节。"}, {"id": "IMG006", "cat": "外籍入职与签证", "en": "Please prepare all the required visa documents before the deadline.", "zh": "请在截止日期前准备好所有必需的签证材料。"}, {"id": "IMG007", "cat": "外籍入职与签证", "en": "We'll submit your documents to the immigration authorities next week.", "zh": "我们下周会将你的材料提交给出入境管理部门。"}, {"id": "IMG008", "cat": "外籍入职与签证", "en": "We expect your residence permit to be ready within seven business days, subject to processing times.", "zh": "预计你的居留许可将在七个工作日内办妥，具体以实际审批进度为准。"}, {"id": "IMG009", "cat": "外籍入职与签证", "en": "This employment verification letter is required for your visa extension.", "zh": "办理签证延期需要这份在职证明。"}, {"id": "IMG010", "cat": "外籍入职与签证", "en": "The company covers the cost of your international health insurance.", "zh": "公司承担你的国际医疗保险费用。"}, {"id": "IMG011", "cat": "绩效管理", "en": "Your performance meets the expectations for your role.", "zh": "你的工作表现达到了岗位要求。"}, {"id": "IMG012", "cat": "绩效管理", "en": "This aspect of your work still needs improvement.", "zh": "这方面的工作仍需改进。"}, {"id": "IMG013", "cat": "绩效管理", "en": "We'll set clear improvement goals together.", "zh": "我们将一起制定明确的改进目标。"}, {"id": "IMG014", "cat": "绩效管理", "en": "Please fill out your self-assessment form in advance.", "zh": "请提前填写自我评估表。"}, {"id": "IMG015", "cat": "绩效管理", "en": "We'll review your progress every two weeks.", "zh": "我们将每两周回顾一次你的工作进展。"}, {"id": "IMG016", "cat": "总部对接汇报", "en": "Please review the attached workforce report.", "zh": "请查阅附件中的人力报表。"}, {"id": "IMG017", "cat": "总部对接汇报", "en": "The monthly employee turnover figures have been updated in the table.", "zh": "表格中的月度员工流失数据已更新。"}, {"id": "IMG018", "cat": "总部对接汇报", "en": "Our current headcount is within the approved annual headcount budget.", "zh": "目前的人员数量在已批准的年度编制预算范围内。"}, {"id": "IMG019", "cat": "总部对接汇报", "en": "We manage labor costs by optimizing staffing levels.", "zh": "我们通过优化人员配置来控制人工成本。"}, {"id": "IMG020", "cat": "总部对接汇报", "en": "I'll brief everyone on all identified risks during our virtual meeting.", "zh": "我会在视频会议中向大家同步所有已识别的风险。"}];
function oralData(){return STORE.oral??={seen:[],favorites:[],wrong:{},history:[]}}
function cleanOral(x){const ids=new Set(SPOKEN.map(r=>r.id));const list=a=>Array.isArray(a)?[...new Set(a.filter(v=>ids.has(v)))]:[];return {seen:list(x?.seen),favorites:list(x?.favorites),wrong:Object.fromEntries(Object.entries(x?.wrong||{}).filter(([k,v])=>ids.has(k)&&Number(v)>0).map(([k,v])=>[k,Number(v)])),history:Array.isArray(x?.history)?x.history.filter(r=>r&&typeof r.date==='string'&&Number.isFinite(r.correct)&&Number.isFinite(r.total)).slice(-200):[]}}
let oral={cat:'all',scope:'all',mode:'learn',index:0,reveal:true,q:null};
function oralPool(){let d=oralData();return SPOKEN.filter(r=>(oral.cat==='all'||r.cat===oral.cat)&&(oral.scope==='all'||(oral.scope==='wrong'?d.wrong[r.id]>0:d[oral.scope]?.includes(r.id))))}
function oralView(){let d=oralData(),pool=oralPool(),r=pool[oral.index%Math.max(1,pool.length)],q=oral.q;let top=`<div class="page-head"><div><span class="tag lav">SPEAK WITH CONFIDENCE</span><h1>高频职场口语</h1><p>${SPOKEN.length} 条实用表达 · 已学 ${d.seen.length} · 收藏 ${d.favorites.length}</p></div></div><div class="surface oral-filters"><label for="oralCategory">工作场景</label><select id="oralCategory" class="control" onchange="oralAction('oralCat:'+this.value)">${[['all','全部工作场景'],...Array.from(new Set(SPOKEN.map(x=>x.cat))).map(x=>[x,x])].map(([k,v])=>`<option value="${h(k)}" ${oral.cat===k?'selected':''}>${h(v)}（${SPOKEN.filter(x=>k==='all'||x.cat===k).length}）</option>`).join('')}</select><label for="oralScope">学习范围</label><select id="oralScope" class="control" onchange="oralAction('oralScope:'+this.value)">${Object.entries({all:'全部表达',seen:'已学',favorites:'收藏',wrong:'错题'}).map(([k,v])=>`<option value="${k}" ${oral.scope===k?'selected':''}>${v}</option>`).join('')}</select><div class="oral-modes">${Object.entries({learn:'学习',practice:'练习',test:'检验',history:'记录'}).map(([k,v])=>`<button class="chip ${oral.mode===k?'active':''}" data-action="oralMode:${k}">${v}</button>`).join('')}</div><p class="muted tiny">当前场景：${oral.cat==='all'?'全部':h(oral.cat)} · ${pool.length} 条匹配表达 · 默认美音</p></div>`;
if(oral.mode==='history')return top+`<div class="surface">${d.history.filter(x=>oral.cat==='all'||x.cat===oral.cat).slice().reverse().map(x=>`<div class="setting-row"><span>${h(x.date)} · ${h(x.cat||"历史记录")}</span><b>${x.correct}/${x.total}</b></div>`).join('')||'暂无口语检验记录'}</div>`;
if(!r&&!(oral.mode==='test'&&q))return top+'<div class="empty">当前范围暂无表达，请切换范围。</div>';
if(oral.mode==='test'){if(!q)return top+`<div class="surface hr-stack"><h2>口语理解检验</h2><p>随机抽取 ${Math.min(10,pool.length)} 条，支持听力和英文理解。</p><button class="primary" data-action="oralStart:text">英文理解</button><button class="secondary" data-action="oralStart:listen">听力检验</button></div>`;if(q.i>=q.items.length)return top+`<div class="surface"><h2>检验完成</h2><p>答对 ${q.correct}/${q.items.length}</p><button class="primary" data-action="oralMode:test">再练一次</button></div>`;let x=q.items[q.i];return top+`<div class="surface hr-stack"><p>第 ${q.i+1}/${q.items.length} 题</p><h2>${q.type==='listen'?'听音选择中文':h(x.r.en)}</h2><button class="secondary" data-action="oralHear:${x.r.id}">播放美音</button>${x.opts.map((v,i)=>`<button class="quiz-option ${x.chosen!==null?(v===x.r.zh?'correct':i===x.chosen?'wrong':''):''}" data-action="oralAnswer:${i}" ${x.chosen!==null?'disabled':''}>${h(v)}</button>`).join('')}${x.chosen!==null?`<div class="quiz-explain">${h(x.r.en)}<br>${h(x.r.zh)}</div><button class="primary" data-action="oralNextQ">下一步</button>`:''}</div>`}
return top+`<div class="surface hr-stack"><span class="tag lav">${h(r.cat)} · ${oral.index+1}/${pool.length}</span>${oral.mode==='learn'?`<h2>${h(r.en)}</h2><p>${h(r.zh)}</p><button class="secondary" data-action="oralHear:${r.id}">听美音</button>`:`<h2>${h(r.zh)}</h2><p class="muted">先尝试用英语表达，可使用系统键盘听写。</p><textarea id="oralInput" rows="3" placeholder="输入你的英文表达" style="width:100%;font:inherit;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--paper);color:var(--text)"></textarea><button class="secondary" data-action="oralReveal">查看参考表达</button><div id="oralReference" hidden><b>${h(r.en)}</b><p>请对照语义与用词，自行判断；不提供自动发音评分。</p><button class="secondary" data-action="oralHear:${r.id}">听参考美音</button></div>`}<button class="secondary" data-action="oralFav:${r.id}">${d.favorites.includes(r.id)?'♥ 已收藏':'♡ 收藏表达'}</button><button class="primary" data-action="oralLearn:${r.id}">标记已学并继续</button><div class="update-buttons"><button class="secondary" data-action="oralMove:-1">上一条</button><button class="secondary" data-action="oralMove:1">下一条</button></div></div>`}
function oralSpeak(text){const synth=window.speechSynthesis;if(!synth||!window.SpeechSynthesisUtterance){toast('当前浏览器不支持语音播放');return}const voices=synth.getVoices().filter(v=>v.lang.replace('_','-').toLowerCase()==='en-us');const voice=voices.find(v=>v.localService&&/premium|enhanced/i.test(v.name))||voices.find(v=>v.localService)||voices[0];if(!voice){toast('美式语音尚未就绪，请安装英语（美国）语音包后重试');return}const spoken=text.replace(/401\(k\)/gi,'four oh one K').replace(/\bKPIs\b/g,'K P I s').replace(/\bKPI\b/g,'K P I').replace(/\bQ3\b/g,'Q three');const u=new SpeechSynthesisUtterance(spoken);u.lang='en-US';u.voice=voice;u.rate=Number(STORE.rate)||1;u.pitch=1;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('美音播放失败，请重试')};synth.speak(u)}
function oralAction(a){let [op,k]=a.split(':');if(!op.startsWith('oral'))return false;let d=oralData(),r=SPOKEN.find(x=>x.id===k);if(op==='oralHear'){if(r){speechStop();oralSpeak(r.en)}return true}if(op==='oralReveal'){document.getElementById('oralReference').hidden=false;return true}if(op==='oralCat'||op==='oralScope'||op==='oralMode'){speechStop();oral[op==='oralCat'?'cat':op==='oralScope'?'scope':'mode']=k;oral.index=0;oral.q=null}else if(op==='oralMove'){oral.index=(oral.index+Number(k)+oralPool().length)%Math.max(1,oralPool().length)}else if(op==='oralFav'&&r){d.favorites=d.favorites.includes(k)?d.favorites.filter(x=>x!==k):[...d.favorites,k];save();oral.index=Math.min(oral.index,Math.max(0,oralPool().length-1))}else if(op==='oralLearn'&&r){if(!d.seen.includes(k))d.seen.push(k);save();oral.index=(oral.index+1)%Math.max(1,oralPool().length)}else if(op==='oralStart'){oral.q={type:k,i:0,correct:0,items:shuffleQuizWords(oralPool()).slice(0,10).map(r=>({r,chosen:null,opts:shuffleQuizWords([r.zh,...shuffleQuizWords(SPOKEN.filter(x=>x.zh!==r.zh)).slice(0,3).map(x=>x.zh)])}))}}else if(op==='oralAnswer'){let q=oral.q,x=q?.items[q.i];if(!x||x.chosen!==null)return true;x.chosen=Number(k);if(x.opts[x.chosen]===x.r.zh){q.correct++;delete d.wrong[x.r.id]}else d.wrong[x.r.id]=(d.wrong[x.r.id]||0)+1;save()}else if(op==='oralNextQ'){let q=oral.q;if(q?.items[q.i]?.chosen===null)return true;if(q.i<q.items.length){q.i++;if(q.i===q.items.length){d.history.push({date:new Date().toLocaleString(),correct:q.correct,total:q.items.length,cat:oral.cat,scope:oral.scope,type:q.type});save()}}}render();return true}

window.hrBoot(85,"正在恢复学习记录并绘制界面…");
render();
window.hrBoot(100,"加载完成");clearTimeout(window.hrBootTimer);document.getElementById("boot").remove();
